import { CommandPalette, type Command, type CommandPaletteSelectDetail } from '@absoluteui/components/command-palette';

const commands: Command[] = [
  { id: 'go-home', label: 'Go to dashboard', group: 'Navigation', icon: 'menu', run: () => { location.hash = '#/'; } },
  { id: 'go-people', label: 'Go to people', group: 'Navigation', keywords: ['employees', 'directory'], run: () => { location.hash = '#/people'; } },
  { id: 'leave', label: 'Request leave', group: 'Actions', shortcut: 'Mod+Shift+L', run: () => { location.hash = '#/leave/new'; } },
  { id: 'theme', label: 'Change theme', group: 'Actions', children: [
    { id: 'theme-light', label: 'Light' },
    { id: 'theme-dark', label: 'Dark' },
  ] },
];
const host = document.createElement('div');
document.body.append(host);
const palette = CommandPalette.create(host, {
  commands,
  providers: [{
    id: 'people',
    label: 'People',
    minQueryLength: 2,
    search: async (query, { signal }) => {
      const res = await fetch(`/api/people?q=${encodeURIComponent(query)}`, { signal });
      const people = (await res.json()) as { id: string; name: string }[];
      return people.map((p) => ({ id: `person-${p.id}`, label: p.name, icon: 'search' }));
    },
  }],
});
host.addEventListener('aui-select', (event) => {
  const { id } = (event as CustomEvent<CommandPaletteSelectDetail>).detail;
  if (id.startsWith('theme-')) document.documentElement.dataset.theme = id.slice(6);
});
const button = document.createElement('button');
button.textContent = 'Search';
button.addEventListener('click', () => { palette.open(); });
document.body.append(button);

import { CommandPalette } from '@absoluteui/components/command-palette';

const host = document.createElement('div');
document.body.append(host);
const saved = sessionStorage.getItem('recent-commands');
const palette = CommandPalette.create(host, {
  shortcut: 'Mod+Shift+P',
  recent: saved ? (JSON.parse(saved) as string[]) : [],
  commands: [
    { id: 'save', label: 'Save', shortcut: 'Mod+S' },
    { id: 'print', label: 'Print', shortcut: 'Mod+P' },
  ],
});
host.addEventListener('aui-close', () => {
  sessionStorage.setItem('recent-commands', JSON.stringify(palette.recent));
});
